$store=$core->get('account_store');$notices=new Notifications($store,$accounts);$mail=new Mail($store);$mailOps=new MailAdmin($store,$mail,$core->migrator());$worker=new AISkillsHub\Core\Accounts\MailWorker($store,$mail,new AISkillsHub\Core\Accounts\Locks($db));
$member=p12_user('noticeowner');$other=p12_user('noticeother');$skill=p12_skill('notices');$review=p12_review($member,$skill,4);
wp_set_current_user($member);$sub=$submissions->save(0,['kind'=>'submit','locale'=>'zh_CN','source_kind'=>'manual','name'=>'通知测试 '.$run,'summary'=>'合成投稿测试数据','notes'=>'仅在隔离测试环境中生成'],0,'submit',p12_key());
