p12_case('notification_idempotency_ownership_atomic_read',function()use($store,$notices,$member,$other,$notice,$foreign,$key){wp_set_current_user($member);p12_assert($store->notify($member,$key,'password_changed','en_US')===$notice,'Replay one durable notice');$before=$store->unreadCount($member);p12_reject(fn()=>$notices->read([$notice,$foreign]),'Cross-owner batch denied');p12_assert($store->unreadCount($member)===$before,'Partial reads rolled back');$notices->read([$notice]);$notices->read([$notice]);p12_assert($store->unreadCount($member)===$before-1,'Read replay idempotent');p12_assert($store->unreadCount($other)>0,'Other account unread unchanged');});
p12_case('notification_filters_private_projection_and_current_target',function()use($notices,$member,$sub,$submissions,$store,$db,$review,$community){wp_set_current_user($member);$rows=$notices->mine('zh_CN',1,'contribution')['notifications'];p12_assert(count($rows)>0,'Contribution filter has notices');foreach($rows as$r){p12_assert($r['type']==='contribution'&&!isset($r['params_json'],$r['subject_id'],$r['subject_type']),'No private payload/target snapshot');p12_assert(is_string($r['target_url'])&&str_contains($r['target_url'],'/zh/account/submission/'),'Current owned submission link');}$submissions->withdraw((int)$sub['id'],(int)$sub['revision'],p12_key());foreach($notices->mine('zh_CN',1,'contribution')['notifications']as$r){p12_assert($r['target_url']===null,'Withdrawn subject has no clickable destination');}$current=$db->row('SELECT * FROM '.$db->table('reviews').' WHERE id=%d',[(int)$review['id']]);$community->withdrawReview((int)$review['id'],(int)$current['lock_version'],p12_key());foreach($notices->mine('en_US',1,'community')['notifications']as$r){p12_assert($r['target_url']===null,'Withdrawn review no link');}});
p12_case('notification_pagination_no_duplicates_and_foreign_exclusion',function()use($store,$notices,$member,$foreign,$run){for($i=0;$i<25;$i++)$store->notify($member,hash('sha256',$run.':page:'.$i),'sessions_revoked','en_US');wp_set_current_user($member);$a=$notices->mine('en_US',1,'account')['notifications'];$b=$notices->mine('en_US',2,'account')['notifications'];p12_assert(count($a)===21&&count($b)>0,'Sentinel pagination bounded21');p12_assert(!array_intersect(array_column(array_slice($a,0,20),'id'),array_column($b,'id')),'Displayed pages disjoint');p12_assert(!in_array((string)$foreign,array_column($a,'id'),true),'Foreign ID absent');});
p12_case('optional_preferences_do_not_disable_security_or_delete_history',function()use($store,$notices,$member,$review,$sub,$run,$core){wp_set_current_user($member);$privacy=$core->get('account_privacy');$before=$store->unreadCount($member);$privacy->savePreferences(['public_profile'=>false,'notification_preferences'=>['account_notifications'=>false,'community_notifications'=>false,'contribution_notifications'=>false,'optional_email'=>false,'locale'=>'en_US']]);p12_assert(get_user_meta($member,'_aish_public_profile',true)!=='1','Public profile preference retained');p12_assert($store->notify($member,hash('sha256',$run.':optaccount'),'profile_updated','en_US')===0,'Optional account suppressed');p12_assert($store->notifyCommunity($member,hash('sha256',$run.':optcommunity'),'review_approved','en_US','review',(int)$review['id'])===0,'Optional review suppressed');p12_assert($store->notifyContribution($member,hash('sha256',$run.':optcontribution'),'contribution_accepted','en_US','submission',(int)$sub['id'])===0,'Optional contribution suppressed');p12_assert($store->notify($member,hash('sha256',$run.':mandatory'),'password_changed','en_US')>0,'Security remains mandatory');p12_assert($store->unreadCount($member)>=$before,'Existing history preserved');});
p12_case('privacy_preferences_preserve_developer_owned_optin',function()use($core,$developers,$member,$run){wp_set_current_user($member);$developers->saveProfile(['handle'=>'ops-'.$run,'opt_in'=>true,'translations'=>['en_US'=>['display_name'=>'Synthetic Operations Contributor','bio'=>'Private QA draft, no real profile.']]],0,p12_key());$privacy=$core->get('account_privacy');$current=$privacy->preferences();p12_assert($current['public_profile']===true,'Native developer flow owns opt-in');$privacy->savePreferences($current);p12_assert(get_user_meta($member,'_aish_public_profile',true)==='1','Notification preference save preserves opt-in');$current['public_profile']=false;p12_reject(fn()=>$privacy->savePreferences($current),'Preference endpoint cannot bypass developer consent workflow');});
p12_case('pending_email_manager_recovery_and_subscriber_denial',function()use($mailOps,$admin){$pending=p12_user('mailpending',false);wp_set_current_user($admin);wp_update_user(['ID'=>$pending,'role'=>'administrator']);wp_set_current_user($pending);p12_assert(is_array($mailOps->configuration()),'Native pending-email administrator can recover mail configuration');$ordinary=p12_user('mailunverified',false);wp_set_current_user($ordinary);p12_reject(fn()=>$mailOps->configuration(),'Nonmanager pending identity denied');wp_set_current_user($admin);});
$queue=function()use($mail,$member,$db):int{$id=$mail->queueSecurity($member,get_userdata($member)->user_email,'en_US','password_changed');$db->execute('UPDATE '.$db->table('notification_outbox')." SET available_at='2000-01-01 00:00:00' WHERE id=%d",[$id]);return$id;};
$row=fn($id)=>$db->row('SELECT * FROM '.$db->table('notification_outbox').' WHERE id=%d',[$id]);
$mockOutcome=false;$definite=false;add_filter('pre_wp_mail',static function()use(&$mockOutcome){return $mockOutcome;},PHP_INT_MAX);add_filter('aish_account_mail_rejection_is_definite',static function()use(&$definite){return $definite;},PHP_INT_MAX);
p12_case('mail_permission_redaction_preview_and_truthful_configuration',function()use($mailOps,$member,$admin,$queue){wp_set_current_user($member);p12_reject(fn()=>$mailOps->listing(),'Subscriber mail dashboard denied');wp_set_current_user($admin);$queue();$json=wp_json_encode($mailOps->listing());foreach(['payload_ciphertext','destination_hash','key_version','lease_token','@example.invalid']as$secret)p12_assert(!str_contains($json,$secret),'Secret field absent');foreach(['zh_CN','en_US']as$l){$p=Mail::preview('verify_email',$l);p12_assert(!str_contains($p['body'],'http')&&!str_contains($p['body'],'token='),'Preview has no credential link');}p12_assert($mailOps->configuration()['transport_verified']===false,'No real transport claim');});
p12_case('mail_definite_rejection_retry_no_business_replay',function()use($mailOps,$admin,$queue,$row,$worker,$db,$member,&$mockOutcome,&$definite){wp_set_current_user($admin);$id=$queue();$db->execute('UPDATE '.$db->table('notification_outbox')." SET available_at='1999-01-01 00:00:00' WHERE id=%d",[$id]);$before=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type IN ('review','submission')");$mockOutcome=false;$definite=true;$worker->run();$r=$row($id);p12_assert($r['status']==='retry'&&(int)$r['attempts']===1&&$r['payload_ciphertext']!==null,'Definite transport rejection retains encrypted retry');$mailOps->retry($id);p12_reject(fn()=>$mailOps->retry($id),'Immediate retry replay rejected',['mail_not_retryable']);p12_assert((int)$row($id)['attempts']===1,'Scheduling does not reset attempts');$db->execute('UPDATE '.$db->table('notification_outbox')." SET available_at='1999-01-01 00:00:00' WHERE id=%d",[$id]);$mockOutcome=true;$worker->run();$r=$row($id);p12_assert($r['status']==='accepted'&&$r['accepted_at']!==null&&$r['payload_ciphertext']===null,'Mock acceptance recorded, ciphertext cleared');p12_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type IN ('review','submission')")===$before,'No review or submission business replay');p12_reject(fn()=>$mailOps->retry($id),'Accepted mail never replayed',['mail_not_retryable']);});
p12_case('mail_uncertain_not_retried_and_pause_resumes_without_send',function()use($queue,$db,$worker,$row,$mailOps,&$mockOutcome,&$definite){$id=$queue();$db->execute('UPDATE '.$db->table('notification_outbox')." SET available_at='1998-01-01 00:00:00' WHERE id=%d",[$id]);$mockOutcome=false;$definite=false;$worker->run();p12_assert($row($id)['status']==='uncertain'&&$row($id)['payload_ciphertext']===null,'Unknown transport outcome tombstoned');p12_reject(fn()=>$mailOps->retry($id),'Unknown delivery never resent',['mail_not_retryable']);$next=$queue();$before=$row($next);$mailOps->pause(true);$worker->run();p12_assert($row($next)===$before,'Paused worker does not claim');$mailOps->pause(false);p12_assert($row($next)===$before,'Resume only schedules, no send');});
p12_case('mail_interruption_recovery_distinguishes_presend_and_sending',function()use($queue,$db,$mailOps,$row){$a=$queue();$b=$queue();$t=$db->table('notification_outbox');$db->execute("UPDATE $t SET status='claimed',attempts=1,lease_token='synthetic',locked_until='2000-01-01 00:00:00' WHERE id=%d",[$a]);$db->execute("UPDATE $t SET status='sending',attempts=1,lease_token='synthetic',locked_until='2000-01-01 00:00:00' WHERE id=%d",[$b]);$mailOps->recover();p12_assert($row($a)['status']==='retry'&&$row($a)['payload_ciphertext']!==null,'Interrupted before send safely retryable');p12_assert($row($b)['status']==='uncertain'&&$row($b)['payload_ciphertext']===null,'Interrupted during send stays uncertain');});
p12_report('Real WordPress/MySQL notification ownership, encrypted outbox and worker transitions; ALL mail acceptance/rejection responses are Mock, no external SMTP/delivery');
